def get_patient_guide(category_code: str) -> dict:
    """분류코드(A~H, S1~S7)에 맞는 환자 설명 블록을 반환.

    반환 dict 키:
      이름, 환자안내문, 바르는법, 기간, 주의, 강도행(스테로이드만)
    앱 전환 시 이 함수 그대로 재사용 가능.
    """
    code = (category_code or "").strip()
    if code.startswith("S"):
        try:
            g = int(code[1:])
        except ValueError:
            g = 4
        row_idx = _STEROID_ROW.get(g, 1)
        row = PATIENT_GUIDE["스테로이드_강도별"]["등급표"][row_idx]
        return {
            "이름": f"스테로이드 {g}등급",
            "환자안내문": (
                f"이 약은 {row['강도']} 스테로이드 연고입니다. "
                f"주로 {row['부위']}에 사용하며, {row['피해야할곳']}에는 바르지 않습니다. "
                f"사용 기간: {row['기간']}. "
                "증상이 좋아지면 갑자기 끊지 말고 의사 지시에 따라 서서히 줄이세요."
            ),
            "바르는법": "환부에 하루 1~2회 얇게 펴 바릅니다. (FTU 기준 참고)",
            "기간": row["기간"],
            "주의": "\n".join(PATIENT_GUIDE["스테로이드_강도별"]["공통주의"]),
            "강도행": row,
        }
    block = PATIENT_GUIDE["효능군별"].get(code)
    if block:
        return {
            "이름": block["이름"],
            "환자안내문": block["환자안내문"],
            "바르는법": block["바르는법"],
            "기간": block["기간"],
            "주의": block["주의"],
        }
    # 매핑 없으면 공통 사용법만
    return {
        "이름": "외용제",
        "환자안내문": "처방 의사의 지시에 따라 환부에 얇게 바르세요.",
        "바르는법": "환부에 얇게.",
        "기간": "처방 지시에 따릅니다.",
        "주의": "",
    }


