def get_qna_for_category(category_code: str) -> list:
    """선택한 약의 분류코드에 맞는 Q&A 항목만 추려서 반환.

    category_code: "S1"~"S7" → 스테로이드, "A"~"H" → 해당 효능군.
    "공통" 태그는 항상 포함. 반환: [{"Q":..., "A":...}, ...]
    """
    code = (category_code or "").strip()
    target = "스테로이드" if code.startswith("S") else code
    result = []
    for grp in PATIENT_QNA["그룹"]:
        for item in grp["항목"]:
            tags = item.get("태그", [])
            if "공통" in tags or target in tags:
                result.append({"Q": item["Q"], "A": item["A"]})
    return result


def _norm(s) -> str:
    """검색 비교용 정규화: 문자열화 + 공백 제거 + 소문자."""
    if s is None:
        return ""
    return "".join(str(s).split()).lower()


def _s(v) -> str:
    """None 안전 문자열 변환."""
    if v is None:
        return ""
    s = str(v).strip()
    return "" if s.lower() == "nan" else s


