def load_ointment_data():
    """내장 데이터(OINTMENT_DATA)를 복사해 공통 스키마 레코드 목록과 메시지를 반환."""
    rows = [dict(r) for r in OINTMENT_DATA]
    # 복합제(D)에 든 스테로이드 성분 → 등급 도출
    for r in rows:
        r["복합스테로이드등급"] = None
        if (r.get("구분") == "일반" and r.get("분류코드") == "D"
                and r.get("등급_int") is None):
            ingr = _s(r.get("성분(국문)"))
            for kw, g in COMBO_STEROID_GRADE.items():
                if kw in ingr:
                    r["복합스테로이드등급"] = g
                    break
    steroid = sum(1 for r in rows if r.get("구분") == "스테로이드")
    general = sum(1 for r in rows if r.get("구분") == "일반")
    notes = [f"스테로이드 {steroid}건", f"일반 연고 {general}건"]
    return rows, notes


def search_ointments(rows, query="", cat_filter=""):
    """검색어(부분일치)와 분류 필터(S=스테로이드 전체, A~H)를 AND 조합해 필터링."""
    res = list(rows)
    if cat_filter:
        if cat_filter == "S":
            res = [r for r in res if r.get("구분") == "스테로이드"]
        else:
            res = [r for r in res if r.get("분류코드") == cat_filter]
    qn = _norm(query)
    if qn:
        res = [r for r in res
               if any(qn in _norm(r.get(col, "")) for col in SEARCH_COLS)]
    # 다단계 stable 정렬: 구분 내림차순, 분류코드/성분/제형 오름차순
    res.sort(key=lambda r: _norm(r.get("제형", "")))
    res.sort(key=lambda r: _norm(r.get("성분(국문)", "")))
    res.sort(key=lambda r: _s(r.get("분류코드", "")))
    res.sort(key=lambda r: _s(r.get("구분", "")), reverse=True)
    return res


# 제품명 끝에 붙는 제형 접미어 (브랜드명만 뽑을 때 제거)
_DOSAGE_SUFFIXES = (
    "카타플라스마", "외용액", "점안액", "점안", "스프레이", "겔", "연고",
    "크림", "로션", "액", "밀크로션", "패취", "패치",
)


def _brand_of(product_name: str) -> str:
    """제품명에서 괄호·용량 정보를 뗀 브랜드 부분을 반환.

    예) "프로솔로션(클로베타솔프로피오네이트)_(55mg/110mL)" -> "프로솔로션"
    """
    name = _s(product_name)
    for sep in ("(", "_", "[", "/"):
        name = name.split(sep)[0]
    return name.strip()


def _strip_dosage(brand: str) -> str:
    """브랜드명 끝의 제형 접미어를 한 번 제거. 예) "프로솔로션" -> "프로솔"."""
    for suf in _DOSAGE_SUFFIXES:
        if brand.endswith(suf) and len(brand) > len(suf) + 1:
            return brand[: -len(suf)]
    return brand


def _matched_brand_frags(rows, text):
    """정규화 텍스트에 매칭된 브랜드 후보(정규화 문자열 -> 매칭 길이).

    - 완전 포함: 브랜드/제형 접미어 strip 브랜드가 텍스트에 통째로 등장(2자 이상).
    - 부분 일치 보강: DB 제품명에는 제조사 접두어가 붙는 경우가 있어(예:
      "삼아리도멕스크림") 약 상자의 큰 글씨("리도멕스")와 완전 일치하지 않는다.
      최장 공통 부분문자열이 한글/영문 4자 이상이면 그 조각을 후보로 등록한다.
    """
    found: dict[str, int] = {}

    def _add(frag: str, size: int):
        if frag not in found or size > found[frag]:
            found[frag] = size

    for r in rows:
        brand = _brand_of(r.get("제품명"))
        if not brand:
            continue
        for cand in {brand, _strip_dosage(brand)}:
            cn = _norm(cand)
            if len(cn) >= 2 and cn in text:
                _add(cn, len(cn))
        bn = _norm(brand)
        if len(bn) >= 4:
            m = difflib.SequenceMatcher(None, bn, text, autojunk=False) \
                .find_longest_match(0, len(bn), 0, len(text))
            if 4 <= m.size < len(bn):
                frag = bn[m.a:m.a + m.size]
                # 숫자·기호 조각("0.3%" 등) 배제 — 한글/영문 조각만 인정
                if re.fullmatch(r"[가-힣a-z]+", frag):
                    _add(frag, m.size)
    return found


def _matched_ingredients(rows, text):
    """정규화 텍스트에 등장하는 성분(국문) 후보(원문 -> 정규화 문자열)."""
    found: dict[str, str] = {}
    for r in rows:
        cand = _s(r.get("성분(국문)"))
        cn = _norm(cand)
        if len(cn) >= 2 and cn in text:
            found[cand] = cn
    return found


_FUZZY_RATIO = 0.75  # 자모 단위 유사도 임계값


def _jamo(s: str) -> str:
    """한글 음절을 자모로 분해. OCR 오독은 대개 자모 일부만 틀리므로
    ("멕"→"메") 자모 단위로 비교해야 유사도가 정확히 나온다."""
    out = []
    for ch in s:
        code = ord(ch)
        if 0xAC00 <= code <= 0xD7A3:
            code -= 0xAC00
            cho, jung, jong = code // 588, (code % 588) // 28, code % 28
            out.append(chr(0x1100 + cho))
            out.append(chr(0x1161 + jung))
            if jong:
                out.append(chr(0x11A7 + jong))
        else:
            out.append(ch)
    return "".join(out)


def _fuzzy_brand_matches(rows, ocr_text):
    """OCR 오독을 견디는 유사도 기반 브랜드 매칭(정확 매칭 실패 시 폴백용).

    상표 로고의 스타일된 글씨는 OCR이 자주 틀린다(예: "삼아 리도멕스" →
    "아리도메스"). OCR 각 줄(한글/영문만 남김)과 DB 브랜드명의 자모 단위
    유사도가 _FUZZY_RATIO 이상이면 해당 DB 브랜드(제형 접미어 strip)를
    후보로 반환. 줄마다 가장 유사한 브랜드 하나만 채택해 잡음을 줄인다.
    """
    text = _norm(ocr_text)
    # 성분명이 그대로 적힌 줄은 제외(성분 유래 제네릭 브랜드 오탐 방지)
    ingredients = set(_matched_ingredients(rows, text).values())

    found: dict[str, int] = {}
    for line in str(ocr_text or "").splitlines():
        cleaned = re.sub(r"[^가-힣a-z]", "", _norm(line))
        if len(cleaned) < 4:
            continue
        if any(cleaned in ing or ing in cleaned for ing in ingredients):
            continue
        best = None  # (ratio, len, brand)
        for r in rows:
            brand = _brand_of(r.get("제품명"))
            # 제형 접미어(크림/로션 등)를 뗀 변형과도 비교해야 상자의
            # 큰 글씨(접미어 없음)와의 유사도가 제대로 나온다
            for variant in {brand, _strip_dosage(brand)}:
                bn = re.sub(r"[^가-힣a-z]", "", _norm(variant))
                if len(bn) < 4 or abs(len(bn) - len(cleaned)) > len(bn):
                    continue
                # 줄이 브랜드보다 길면 브랜드 길이 창을 밀며 최고 유사도 탐색
                windows = (
                    [cleaned] if len(cleaned) <= len(bn) + 2 else
                    [cleaned[i:i + len(bn) + 1]
                     for i in range(len(cleaned) - len(bn))]
                )
                bj = _jamo(bn)
                for w in windows:
                    sm = difflib.SequenceMatcher(None, bj, _jamo(w),
                                                 autojunk=False)
                    if sm.real_quick_ratio() < _FUZZY_RATIO:
                        continue
                    ratio = sm.ratio()
                    if ratio >= _FUZZY_RATIO:
                        cand = (ratio, len(bn), _strip_dosage(variant))
                        if best is None or cand > best:
                            best = cand
        if best:
            _, size, brand = best
            if brand not in found or size > found[brand]:
                found[brand] = size
    return found


def match_products_from_text(rows, ocr_text, limit=8):
    """카메라 OCR 텍스트에서 등장하는 제품 브랜드/성분 후보를 점수순으로 반환.

    - UI 비의존. 데스크톱/웹 공용.
    - 반환: 검색어로 바로 쓸 수 있는 문자열 후보 리스트(중복 제거, 긴 것 우선).
    """
    text = _norm(ocr_text)
    if not text:
        return []

    # 후보 문자열 -> (브랜드 여부, 매칭 길이) 점수.
    # 약 상자에는 브랜드명과 성분명이 함께 인쇄되므로, 성분명이 아무리 길어도
    # 브랜드명이 항상 우선한다(예: 아드반탄 > 메틸프레드니솔론아세포네이트).
    # 브랜드가 하나도 안 잡히면 성분명이 폴백으로 1순위가 된다.
    scored: dict[str, tuple[int, int]] = {}
    for frag, size in _matched_brand_frags(rows, text).items():
        scored[frag] = (1, size)
    if not scored:
        # 정확 매칭된 브랜드가 없으면 OCR 오독 대비 유사도 매칭으로 폴백
        for brand, size in _fuzzy_brand_matches(rows, ocr_text).items():
            scored[brand] = (1, size)
    for cand, cn in _matched_ingredients(rows, text).items():
        key = (0, len(cn))
        if cand not in scored or key > scored[cand]:
            scored[cand] = key

    ordered = sorted(scored, key=lambda c: scored[c], reverse=True)
    return ordered[:limit]


def count_distinct_brands(rows, ocr_text):
    """OCR 텍스트에서 서로 다른 제품 브랜드가 몇 개 보이는지 추정.

    사진에 연고가 2개 이상 찍혔는지 판별하는 용도. 같은 제품에서 나온
    후보들("삼아리도멕스"·"리도멕스")은 부분문자열 관계이므로 한 그룹으로
    묶고, 성분명에 포함되는 조각(성분 표기가 제네릭 브랜드명과 겹치는 경우)은
    별도 제품으로 세지 않는다.
    """
    text = _norm(ocr_text)
    if not text:
        return 0

    ingredients = set(_matched_ingredients(rows, text).values())
    frags = set()
    for f in _matched_brand_frags(rows, text):
        if any(f in ing for ing in ingredients):
            continue
        # "이트크림"처럼 성분 표기와 제형 단어 경계에 걸친 잡음 조각 배제:
        # 제형 접미어를 떼고도 3자 이상 남아야 브랜드로 인정
        f = _strip_dosage(f)
        if len(f) >= 3:
            frags.add(f)

    groups: list[list[str]] = []
    for f in sorted(frags, key=len, reverse=True):
        for grp in groups:
            if any(f in g or g in f for g in grp):
                grp.append(f)
                break
        else:
            groups.append([f])
    return len(groups)
